'use strict';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => Number(n).toLocaleString('lt-LT',{maximumFractionDigits:2});
const R = WorkRules;
const TODAY = '2026-11-25';
const KEY = 'pvm-workforce-demo-v3';
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',project:'<path d="M3 7h6l2-3h10v16H3z"/><path d="M3 9h18"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9V4"/>',check:'<path d="m5 12 4 4L19 6"/><path d="M20 12v7a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h10"/>',car:'<path d="m4 10 2-6h12l2 6M3 10h18v8H3zM6 18v3m12-3v3M6 14h2m8 0h2"/>',home:'<path d="m3 10 9-7 9 7v11H3zM9 21v-8h6v8"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.project}</svg>`;
const B=(label,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
function seed(){
 const names=['Tomas','Mantas','Darius','Lukas','Rokas','Paulius','Andrius','Vilius','Jonas','Arnas','Marius','Giedrius','Saulius','Dovydas','Justas','Tadas','Nerijus','Vytenis','Simas','Donatas'];
 const surnames=['Giraitis','Šilas','Vėjas','Kalnys','Beržas','Smiltis','Upelis','Vingis'];
 const teams=Array.from({length:15},(_,i)=>({id:i+1,name:i<10?`Montavimo komanda ${i+1}`:i<13?`Užbaigimo komanda ${i-9}`:`Elektrikų komanda ${i-12}`,kind:i<10?'Montavimas':i<13?'Užbaigimo darbai':'Elektros darbai',vehicle:i+1}));
 const employees=[];const users=[{id:1001,name:'Įmonės vadovas',kind:'director',canCorrect:true},{id:1002,name:'Administratorius B',kind:'admin',canCorrect:true},{id:1003,name:'Administratorius C · be valandų taisymo',kind:'admin',canCorrect:false}];
 for(const t of teams){const size=t.id<=10?5:t.id<=13?2:7;for(let i=0;i<size;i++){const n=employees.length;const e={id:n+1,name:names[n%20]+' '+surnames[Math.floor(n/20)],team:t.id,job:i===0?'Komandos vadovas':t.id<=10?'Montuotojas':t.id<=13?'Užbaigimo darbų specialistas':'Elektrikas',active:true};employees.push(e);if(i===0)users.push({id:e.id,name:e.name,kind:'supervisor',team:t.id});}}
 const projects=[{id:1,name:'Saulės parkas · Brandenburgas',city:'Brandenburgas, Vokietija',mw:18.5,status:'Vykdomas',managers:[1,6,51,57]},{id:2,name:'Saulės parkas · Saksonija',city:'Saksonija, Vokietija',mw:12,status:'Vykdomas',managers:[11,16,53,64]},{id:3,name:'Komercinis objektas · Hesenas',city:'Hesenas, Vokietija',mw:3.2,status:'Planuojamas',managers:[]}];
 const vehicles=Array.from({length:27},(_,i)=>({id:i+1,plate:`DEMO-${String(i+1).padStart(2,'0')}`,name:['VW Transporter','Ford Transit','Mercedes Sprinter'][i%3],technicalDue:i===0?'2026-11-20':i<4?'2026-12-10':`2027-${String(i%9+1).padStart(2,'0')}-15`,remindDays:30,responsible:'',note:''}));
 const entries=[];for(const date of ['2026-11-23','2026-11-24',TODAY]){for(const e of employees){const owner=users.find(u=>u.team===e.team);const project=e.team%2?1:2;entries.push({id:entries.length+1,date,employee:e.id,author:owner.id,team:e.team,project,vehicle:e.team,driver:owner.id,start:'07:00',end:'17:00',lunchStart:'12:00',attendance:'Dirbo',proposedHours:null,comment:'',status:date===TODAY?'Juodraštis':'Patvirtinta'});}}
 for(const r of entries.filter(r=>r.date===TODAY))r.end='18:30';
 const split=entries.find(r=>r.employee===1&&r.date===TODAY);split.end='11:00';entries.push({...split,id:entries.length+1,project:2,start:'11:00',end:'18:30'});
 const correction=entries.find(r=>r.employee===2&&r.date===TODAY);correction.proposedHours=8;correction.comment='Vadovo pastaba: darbo rezultatų aptarimas. Siūloma korekcija, dirbta 11 val., atlikto darbo įvertinimas – 8 val.';
 const absent=entries.find(r=>r.employee===3&&r.date===TODAY);absent.attendance='Nepateisintas neatvykimas';absent.start='';absent.end='';absent.comment='Neatvyko. Reikia administratoriaus peržiūros.';
 for(const p of projects)p.managers=[...new Set(entries.filter(r=>r.project===p.id).map(r=>r.author))];
 return {schema:3,employees,users,teams,projects,vehicles,entries,expenses:[{id:1,project:1,from:'2026-11-01',to:'2026-11-30',property:'Būstas A',amount:1850,note:'Pavyzdinės komandos apgyvendinimo išlaidos.',author:1001}],requests:[],audit:[]};
}
let db;try{db=JSON.parse(localStorage.getItem(KEY))||seed()}catch{db=seed()}
// Keep saved demo records and update only the company head's role.
const companyHead=db.users.find(u=>u.id===1001);if(companyHead){companyHead.kind='director';companyHead.name='Įmonės vadovas';}
const state={page:'overview',user:1,project:1,employee:1,from:'2026-11-23',to:'2026-11-27',projectFilter:'all',employeeFilter:'all',status:'all',search:'',pageNumber:1};
const actor=()=>db.users.find(u=>u.id===state.user)||db.users[0];const admin=()=>['admin','director'].includes(actor().kind);
const director=()=>actor().kind==='director';
const corrector=()=>admin()&&actor().canCorrect===true;
const employee=id=>db.employees.find(e=>e.id===+id);const project=id=>db.projects.find(p=>p.id===+id);const team=id=>db.teams.find(t=>t.id===+id);const user=id=>db.users.find(u=>u.id===+id);const vehicle=id=>db.vehicles.find(v=>v.id===+id);
const visibleRows=()=>db.entries.filter(r=>admin()||r.author===state.user);
const money=n=>fmt(n)+' €';const num=(rows,f)=>R.round(rows.reduce((s,r)=>s+f(r),0));const actual=rows=>num(rows,r=>R.calculate(r).actual);
const dateTime=()=>new Date().toLocaleString('lt-LT',{timeZone:'Europe/Vilnius'});
const nextId=rows=>Math.max(0,...rows.map(r=>r.id))+1;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{toast('Nepavyko išsaugoti naršyklėje. Eksportuokite suvestinę.')}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function audit(action,details,before='',after='',scope='general'){db.audit.unshift({id:nextId(db.audit),when:dateTime(),actor:actor().name,action,details,before,after,scope});}
const badge=(s)=>`<span class="badge ${({'Vykdomas':'green','Patvirtinta':'green','Pateikta':'orange','Juodraštis':'blue','Planuojamas':'blue','Užbaigtas':'gray','Išspręsta':'green','Laukia taisymo':'red'})[s]||'gray'}">${esc(s)}</span>`;
const options=(rows,selected,label)=>rows.map(r=>`<option value="${r.id}" ${String(r.id)===String(selected)?'selected':''}>${esc(label(r))}</option>`).join('');
const projectOptions=id=>options(db.projects,id,p=>p.name);
const select=(name,content)=>`<select name="${name}" required>${content}</select>`;
let fieldNo=0;function field(label,html,note=''){const id='f-'+(++fieldNo);return `<div class="field"><label for="${id}">${label}</label>${html.replace(/<(input|select|textarea)\b/,`<$1 id="${id}"`)}${note?`<small>${note}</small>`:''}</div>`}
const hint=s=>`<div class="hint">${icon('info')}<span>${s}</span></div>`;
const metric=(label,value,foot,i='clock')=>`<div class="metric"><div class="metric-label">${label}${icon(i)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;
const head=(title,sub,buttons='')=>`<div class="pagehead"><div><div class="eyebrow">Projektai ir darbuotojai</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="actions">${buttons}</div></div>`;
function nav(){return [['overview','grid','Apžvalga'],['time','clock','Darbo valandos'],['dayreview','clock','Dienos suvestinė'],...(admin()?[['coverage','check','Dienos kontrolė']]:[]),['projects','project','Objektai'],['employees','users','Darbuotojai'],['vehicles','car','Automobiliai'],['reports','chart','Suvestinės'],...(director()?[['expenses','home','Būsto išlaidos']]:[]),['requests','check',admin()?'Taisymai ir istorija':'Taisymo prašymai']];}
function render(){const titles={dayreview:'Dienos suvestinė',coverage:'Dienos kontrolė',overview:'Apžvalga',time:'Darbo valandos',projects:'Objektai',detail:'Objekto suvestinė',employees:'Darbuotojai',employee:'Darbuotojo ataskaita',vehicles:'Automobiliai',reports:'Suvestinės',expenses:'Būsto išlaidos',requests:'Taisymai ir istorija'};if((!director()&&state.page==='expenses')||(!admin()&&state.page==='coverage'))state.page='overview';
 $('#app').innerHTML=`<header class="suite">${icon('grid')}<span class="suite-brand">Projektai ir darbuotojai</span><span class="separator"></span><small>Vidinė darbo laiko apskaita</small><div class="suite-end"><button class="pwa-install" type="button" data-pwa-install aria-label="Įdiegti programėlę">${icon('download')}<span>Įdiegti programėlę</span></button><span class="badge" style="background:#ffffff20;color:white">Demo</span></div></header><div class="shell"><aside><div class="brand"><div class="brand-mark">${icon('sun')}</div><div><strong>Komandų valandos</strong><small>Objektai · žmonės · transportas</small></div></div><div class="navlabel">Darbo erdvė</div><nav class="nav" aria-label="Pagrindinė navigacija">${nav().map(([id,i,t])=>`<button data-action="nav" data-page="${id}" class="${state.page===id||(state.page==='detail'&&id==='projects')||(state.page==='employee'&&id==='employees')?'active':''}" title="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><strong>Demonstraciniai duomenys</strong>70 darbuotojų · 27 automobiliai.<br>Įrašai saugomi šioje naršyklėje. Vaidmenys imituojami.</div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Darbo erdvė <span>/</span>${titles[state.page]}</div><div class="rolebox"><label for="role">Išbandyti vaidmenį</label><select id="role">${options(db.users,state.user,u=>u.kind!=='supervisor'?u.name:`${u.name} · ${team(u.team).name}`)}</select></div></header><main class="content" id="main">${({dayreview:dayReviewView,coverage:coverageView,overview,time:timeView,projects:projectsView,detail:projectView,employees:employeesView,employee:employeeView,vehicles:vehiclesView,reports:reportsView,expenses:expensesView,requests:requestsView})[state.page]()}<div class="footer-note"><span>Individualiai programuojamos sistemos prototipas · ${director()?'Įmonės vadovo peržiūra':admin()?'Administravimas ir visų komandų valandos':'Matote tik savo įvestas valandas'}</span><button data-action="reset">Atkurti demo duomenis</button></div></main></div></div>`;
 $('#role').onchange=e=>{state.user=+e.target.value;state.page='overview';resetFilters();render()};bindFilters();window.AppPWA?.refreshButtons();
}
function resetFilters(){state.projectFilter='all';state.employeeFilter='all';state.status='all';state.search='';state.pageNumber=1;}
function periodRows(){return visibleRows().filter(r=>(!state.from||r.date>=state.from)&&(!state.to||r.date<=state.to)&&(state.projectFilter==='all'||r.project===+state.projectFilter)&&(state.employeeFilter==='all'||r.employee===+state.employeeFilter)&&(state.status==='all'||r.status===state.status));}
function filterBar(withStatus=false){return `<div class="toolbar"><div class="filters"><input id="from" type="date" aria-label="Laikotarpio pradžia" value="${state.from}"><input id="to" type="date" aria-label="Laikotarpio pabaiga" value="${state.to}">${state.page==='detail'?'':`<select id="project-filter" aria-label="Objektas"><option value="all">Visi objektai</option>${projectOptions(state.projectFilter)}</select>`}${state.page==='employee'?'':`<select id="employee-filter" aria-label="Darbuotojas"><option value="all">Visi darbuotojai</option>${options(db.employees,state.employeeFilter,e=>e.name)}</select>`}${withStatus?`<select id="status-filter" aria-label="Įrašo būsena"><option value="all">Visos būsenos</option><option ${state.status==='Juodraštis'?'selected':''}>Juodraštis</option><option ${state.status==='Pateikta'?'selected':''}>Pateikta</option><option ${state.status==='Patvirtinta'?'selected':''}>Patvirtinta</option></select>`:''}</div></div>`;}
function bindFilters(){const map={'from':'from','to':'to','project-filter':'projectFilter','employee-filter':'employeeFilter','status-filter':'status','search':'search','review-date':'reviewDate','day-team':'dayTeam'};for(const [id,k] of Object.entries(map))if($('#'+id))$('#'+id).onchange=e=>{state[k]=e.target.value;state.pageNumber=1;render()};}
function overview(){const rs=visibleRows().filter(r=>r.date===TODAY),pending=visibleRows().filter(r=>r.status==='Pateikta');return head('Valandos – be pasimetusių įrašų','Darbuotojai gali tą pačią dieną dirbti keliuose objektuose.',B(icon('plus')+' Pildyti dieną','new-time','','primary'))+`<div class="hero"><div class="hero-text"><span class="pill">KASDIENĖ KOMANDŲ APSKAITA</span><h2>Visa komandos diena – vienoje lentelėje.</h2><p>Pažymėkite dirbusius, pravaikštas ir pateisintus neatvykimus. Dienos gale kiekvienam įrašykite atlikto darbo valandas bei komentarą.</p></div></div><div class="metrics">${metric('Darbuotojų sąraše',db.employees.length,'Galima pildyti ir augant iki 120+','users')}${metric('Faktinės valandos šiandien',fmt(actual(rs))+'<small>val.</small>','Po automatinės pietų pertraukos')}${metric('Laukia peržiūros',pending.length,'Pateikti vadovų įrašai','check')}${metric('Sistemos naudotojai',db.users.length,'Įmonės vadovas, 2 administratoriai ir 15 komandų atstovų','users')}</div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>Valandos pagal objektą</h2>${B('Suvestinės','nav','data-page="reports"','link')}</div>${db.projects.map(p=>{const r=visibleRows().filter(r=>r.project===p.id);return `<div class="project-row"><div><button class="project-name" data-action="detail" data-id="${p.id}">${esc(p.name)}</button><div class="meta">${esc(p.city)} · ${p.managers.length} priskirti vadovai</div></div><strong>${fmt(actual(r))} val.</strong><div>${badge(p.status)}</div></div>`}).join('')}</section><section class="panel"><div class="panel-head"><h2>Reikia dėmesio</h2></div><div class="panel-body"><div class="timeline"><div><h3>${db.requests.filter(r=>r.status==='Laukia taisymo'&&(admin()||r.author===state.user)).length} taisymo prašymai</h3><p class="meta">Pateiktus įrašus koreguoja tik administratorius. Pakeitimai išsaugomi istorijoje.</p>${B('Peržiūrėti','nav','data-page="requests"','link')}</div><div><h3>${dueVehicles().length} automobilių TA terminai</h3><p class="meta">Matykite artėjančias arba jau pasibaigusias technines apžiūras.</p>${B('Automobilių sąrašas','nav','data-page="vehicles"','link')}</div><div><h3>3 užbaigimo ir 2 elektrikų komandos</h3><p class="meta">Jų valandos patenka į tą pačią objekto suvestinę kaip ir montavimo komandų.</p></div></div></div></section></div><div class="spacer"></div>${admin()?coveragePreview():B('Bendra mano komandos diena','nav','data-page="dayreview"')}<div class="spacer"></div>${hint('Faktinis laikas skaičiuojamas iš intervalo. Atlikto darbo valandos ir komentaras įvedami kiekvienam darbuotojui atskirai, nekeičiant jo darbo intervalo.')}`;}
function rowsTable(rows,employeeReport=false){
 const sorted=[...rows].sort((a,b)=>b.date.localeCompare(a.date)||a.employee-b.employee||a.start.localeCompare(b.start));const page=Math.min(state.pageNumber,Math.max(1,Math.ceil(sorted.length/25)));const list=sorted.slice((page-1)*25,page*25);
 return `<div class="panel"><div class="tablewrap"><table class="hours-table"><thead><tr><th>${employeeReport?'Data':'Darbuotojas / data'}</th><th>Objektas / vadovas</th><th>Komanda / automobilis</th><th>Intervalas / pietūs</th><th>Dirbta val.</th><th>Atlikto darbo val.</th><th>Pravaikštos korekcija</th><th>Būsena / veiksmai</th></tr></thead><tbody>${list.map(r=>{const c=R.calculate(r),performed=R.assessed(r),adjustment=R.absenceAdjustment(db.entries,r),d=R.daySummary(visibleRows(),r.employee,r.date),delta=R.round(performed-c.actual);return `<tr><td>${employeeReport?'':`<button class="project-name" data-action="employee" data-id="${r.employee}">${esc(employee(r.employee).name)}</button>`}<div class="meta">${r.date}</div><div class="meta">Diena: ${fmt(d.actual)} dirbta / ${fmt(d.assessed)} atlikta val.</div></td><td><button class="project-name" data-action="detail" data-id="${r.project}">${esc(project(r.project).name)}</button><div class="meta">${esc(user(r.author)?.name||'Administratorius')}</div></td><td>${esc(team(r.team).name)}<div class="meta">${esc(vehicle(r.vehicle)?.plate||'Automobilis nepriskirtas')}${r.driver?'<br>Vairuoja: '+esc(employee(r.driver)?.name||''):''}</div></td><td>${r.attendance==='Dirbo'?`${r.start}–${r.end}<div class="meta">Pietūs: ${c.lunch} min.</div>`:`<span class="badge ${r.attendance==='Nepateisintas neatvykimas'?'red':'gray'}">${esc(r.attendance)}</span>`}</td><td><strong>${fmt(c.actual)} val.</strong></td><td><strong>${fmt(performed)} val.</strong>${delta!==0?`<div class="meta ${delta<0?'negative':''}">Skirtumas ${delta>0?'+':''}${fmt(delta)} val.</div>`:''}${r.comment?`<div class="row-comment">${esc(r.comment)}</div>`:''}</td><td>${r.attendance==='Nepateisintas neatvykimas'?`<strong class="negative">${adjustment===null?'Laukia duomenų':fmt(adjustment)+' val.'}</strong><div class="meta">Komandos dienos vidurkis</div>`:'<span class="meta">—</span>'}</td><td>${badge(r.status)}<div class="actions" style="margin-top:9px">${r.status==='Juodraštis'?(corrector()||r.author===state.user?B('Pildyti dieną','day-sheet',`data-id="${r.id}"`,'small'):''):admin()?`${r.status==='Pateikta'?B('Patvirtinti','approve',`data-id="${r.id}"`,'small'):''}${corrector()?B('Taisyti','edit-time',`data-id="${r.id}"`,'small'):''}`:B('Prašyti taisymo','request-fix',`data-id="${r.id}"`,'small')}</div></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Pagal pasirinktus filtrus įrašų nėra.</td></tr>'}</tbody></table></div><div class="table-total"><span>${sorted.length} įrašai · dirbta ${fmt(actual(sorted))} val. · atlikta ${fmt(num(sorted,R.assessed))} val.</span><div class="actions">${B('Ankstesni','page',`data-page-number="${page-1}" ${page<=1?'disabled':''}`,'small')}<span>${page}/${Math.max(1,Math.ceil(sorted.length/25))}</span>${B('Kiti','page',`data-page-number="${page+1}" ${page*25>=sorted.length?'disabled':''}`,'small')}</div></div></div>`;
}
function timeView(){return head('Darbo valandos','Vienoje lentelėje pažymėkite dalyvavimą ir kiekvieno darbuotojo dienos rezultatą.',B(icon('download')+' CSV','export-time')+B('Perkelti darbuotojus','transfer')+B(icon('plus')+' Pildyti dieną','new-time','','primary'))+filterBar(true)+rowsTable(periodRows())+`<div class="spacer"></div>${hint('Pietų pertrauka – 30 min. pagal įvestą pietų pradžią. Darbuotojui dirbant keliuose objektuose ji paskirstoma pagal intervalų persidengimą su pietumis ir nesidubliuoja. Dienos juodraštį galite tęsti. Pateiktą įrašą taiso administratorius.')}`;}
function projectsView(){const list=db.projects.filter(p=>(p.name+' '+p.city).toLowerCase().includes(state.search.toLowerCase()));return head('Objektai','Suvestinės pagal objekto pavadinimą. Vieną objektą gali pildyti keli darbų vadovai.',admin()?B(icon('plus')+' Pridėti objektą','new-project','','primary'):'')+`<div class="toolbar"><input id="search" aria-label="Ieškoti objekto" placeholder="Ieškoti pagal pavadinimą" value="${esc(state.search)}"></div><div class="project-cards">${list.map(p=>{const rs=visibleRows().filter(r=>r.project===p.id);return `<article class="project-card"><div class="card-top"><div class="project-icon">${icon('project')}</div>${badge(p.status)}</div><h2>${esc(p.name)}</h2><p>${esc(p.city)}${p.mw?' · '+fmt(p.mw)+' MW':''}</p><div class="card-stats"><div><strong>${fmt(actual(rs))} val.</strong><span>Faktiškai išdirbta</span></div><div><strong>${new Set(rs.map(r=>r.employee)).size}</strong><span>Darbuotojai</span></div></div><div class="meta">Vadovai: ${p.managers.map(id=>esc(user(id)?.name||'')).filter(Boolean).join(', ')||'Dar nepriskirti'}</div>${director()?`<div class="meta">Būsto išlaidos: ${money(db.expenses.filter(e=>e.project===p.id).reduce((s,e)=>s+e.amount,0))}</div>`:''}<div class="card-bottom">${badge(p.status)}${B('Atidaryti','detail',`data-id="${p.id}"`,'link')}</div></article>`}).join('')}</div>`;}
function projectView(){const p=project(state.project);const rs=periodRows().filter(r=>r.project===p.id);return head(esc(p.name),`${esc(p.city)} · ${p.managers.length} priskirti vadovai`,B('Visi objektai','nav','data-page="projects"')+B(icon('download')+' Objekto CSV','export-project')+(admin()?B('Keisti objektą','edit-project',`data-id="${p.id}"`):''))+`<div class="metrics">${metric('Faktiškai išdirbta',fmt(actual(rs))+'<small>val.</small>','Visų šio objekto komandų valandos')}${metric('Patvirtintas faktas',fmt(actual(rs.filter(r=>r.status==='Patvirtinta')))+'<small>val.</small>','Patvirtino administratorius','check')}${metric('Darbuotojai',new Set(rs.map(r=>r.employee)).size,'Pagal pasirinktą laikotarpį','users')}${metric(director()?'Būsto išlaidos':'Komandos',director()?money(db.expenses.filter(e=>e.project===p.id).reduce((s,e)=>s+e.amount,0)):new Set(rs.map(r=>r.team)).size,director()?'Visas objekto laikotarpis':'Su šiuo objektu susieti įrašai','home')}</div><section class="panel"><div class="panel-head"><h2>Atsakingi darbų vadovai</h2><span class="meta">Tas pats objektas – keli vadovai</span></div><div class="panel-body"><p>${p.managers.map(id=>esc(user(id)?.name||'')).filter(Boolean).join(', ')||'Vadovai dar nepriskirti'}</p><p class="meta">Administratorius mato visus įrašus, darbų vadovas – tik savo suvestus duomenis.</p></div></section><div class="spacer"></div>`+filterBar()+rowsTable(rs)+(director()?`<div class="spacer"></div>${expenseTable(db.expenses.filter(e=>e.project===p.id))}`:'');}
function employeesView(){const list=db.employees.filter(e=>(e.name+' '+e.job+' '+team(e.team).name).toLowerCase().includes(state.search.toLowerCase()));return head('Darbuotojų sąrašas','Darbuotojai patys prie sistemos nesijungia. Ataskaitą jiems parodo administracija.',admin()?B(icon('plus')+' Pridėti darbuotoją','new-employee','','primary'):'')+`<div class="toolbar"><input id="search" aria-label="Ieškoti darbuotojo" placeholder="Vardas, komanda ar pareigos" value="${esc(state.search)}"><span class="meta">${db.employees.length} darbuotojų · augimas iki maždaug 120</span></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Darbuotojas</th><th>Komanda</th><th>Pareigos</th><th>Savo / visų matomų įrašų faktas</th><th>Ataskaita</th></tr></thead><tbody>${list.map(e=>`<tr><td><strong>${esc(e.name)}</strong></td><td>${esc(team(e.team).name)}</td><td>${esc(e.job)}</td><td>${fmt(actual(visibleRows().filter(r=>r.employee===e.id)))} val.</td><td>${B('Peržiūrėti','employee',`data-id="${e.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div></section>`;}
function employeeView(){const e=employee(state.employee);const rs=periodRows().filter(r=>r.employee===e.id);return head(esc(e.name),`${esc(team(e.team).name)} · ${esc(e.job)} · ataskaita administracijai`,B('Darbuotojų sąrašas','nav','data-page="employees"')+B(icon('download')+' Darbuotojo CSV','export-employee'))+`<div class="metrics">${metric('Faktiškai dirbta',fmt(actual(rs))+'<small>val.</small>','Apskaičiuota iš intervalų')}${metric('Patvirtinta',fmt(actual(rs.filter(r=>r.status==='Patvirtinta')))+'<small>val.</small>','Faktinės valandos','check')}${metric('Neatvykimo dienos',new Set(rs.filter(r=>r.attendance!=='Dirbo').map(r=>r.date)).size,'Priežastis nurodyta įraše','clock')}${metric('Vadovo korekcijos',rs.filter(r=>R.proposal(db.entries,r).delta!==0).length,'Rodomos atskirai, su paaiškinimu','info')}</div>${filterBar()}${dayTotalsPanel(rs,e.id)}<div class="spacer"></div>${hint('Tai darbuotojo ataskaita, kurią atidaro administratorius ar jo duomenis pildęs vadovas. Skaičiuotas faktinis laikas lieka matomas kartu su vadovo komentaru ir siūlymu. Darbuotojo paskyros nereikia.')}<div class="spacer"></div>${rowsTable(rs,true)}`;}
function dueVehicles(){return db.vehicles.filter(v=>v.technicalDue&&Math.ceil((new Date(v.technicalDue)-new Date(TODAY))/86400000)<=v.remindDays);}
function vehiclesView(){return head('Automobiliai ir komandos','27 automobilių parkas. Priskyrimai saugomi kiekvienos darbo dienos įrašuose.',admin()?B(icon('plus')+' Pridėti automobilį','new-vehicle','','primary'):'')+`${hint('Techninės apžiūros terminai ir priminimo nustatymai. Demo rodo perspėjimus ekrane; automatinių el. laiškų siuntimas neprijungtas. Kelionės laikas ir GPS čia nesekami.')}<div class="spacer"></div><section class="panel"><div class="tablewrap"><table><thead><tr><th>Automobilis</th><th>Techninė apžiūra iki</th><th>Perspėjimas</th><th>Priskyrimai</th><th>Veiksmai</th></tr></thead><tbody>${db.vehicles.map(v=>{const due=dueVehicles().some(x=>x.id===v.id);const assignments=[...new Set(visibleRows().filter(r=>r.vehicle===v.id&&r.date===TODAY).map(r=>team(r.team).name))];return `<tr><td><strong>${esc(v.plate)}</strong><div class="meta">${esc(v.name)}</div></td><td>${esc(v.technicalDue||'Neįvesta')}<div class="meta">Prieš ${v.remindDays} d.</div></td><td>${due?`<span class="badge ${v.technicalDue<TODAY?'red':'orange'}">${v.technicalDue<TODAY?'TA pasibaigusi':'Artėja TA'}</span>`:'<span class="badge green">Terminas neartėja</span>'}</td><td>${assignments.map(esc).join(', ')||'<span class="meta">Šiandien nepriskirtas</span>'}</td><td>${admin()?B('Keisti','edit-vehicle',`data-id="${v.id}"`,'small'):'<span class="meta">Peržiūra</span>'}</td></tr>`}).join('')}</tbody></table></div></section>`;}
function reportsView(){const rs=periodRows();return head('Savaitės ir mėnesio suvestinės','Visos komandos ir užbaigimo darbai susumuojami prie to paties objekto.',B(icon('download')+' Eksportas buhalterijai','export-approved'))+filterBar()+`<div class="metrics">${metric('Faktinės valandos',fmt(actual(rs))+'<small>val.</small>','Visos matomos valandos')}${metric('Patvirtintos valandos',fmt(actual(rs.filter(r=>r.status==='Patvirtinta')))+'<small>val.</small>','Eksportui buhalterijai','check')}${metric('Darbuotojai',new Set(rs.map(r=>r.employee)).size,'Pagal laikotarpį ir filtrus','users')}${metric('Objektai',new Set(rs.map(r=>r.project)).size,'Pagal pavadinimą','project')}</div><section class="panel"><div class="panel-head"><h2>Objektų suvestinė</h2><p>Valandos iš visų komandų</p></div><div class="tablewrap"><table><thead><tr><th>Objektas</th><th>Montavimo komandos</th><th>Užbaigimo komandos</th><th>Elektrikai</th><th>Iš viso dirbta</th><th>Atlikto darbo val.</th><th>Pravaikštų korekcijos</th>${director()?'<th>Būsto išlaidos</th>':''}</tr></thead><tbody>${db.projects.map(p=>{const pr=rs.filter(r=>r.project===p.id);return `<tr><td><button class="project-name" data-action="detail" data-id="${p.id}">${esc(p.name)}</button></td>${['Montavimas','Užbaigimo darbai','Elektros darbai'].map(t=>`<td>${fmt(actual(pr.filter(r=>team(r.team).kind===t)))} val.</td>`).join('')}<td><strong>${fmt(actual(pr))} val.</strong></td><td>${fmt(num(pr,R.assessed))} val.</td><td class="negative">${fmt(num(pr,r=>R.absenceAdjustment(db.entries,r)||0))} val.</td>${director()?`<td>${money(db.expenses.filter(e=>e.project===p.id&&e.from<=state.to&&e.to>=state.from).reduce((s,e)=>s+e.amount,0))}<div class="meta">Persidengiančių būsto laikotarpių visa suma</div></td>`:''}</tr>`}).join('')}</tbody></table></div></section><div class="spacer"></div><section class="panel"><div class="panel-head"><h2>Darbuotojų valandos</h2><p>Faktas ir vidinės korekcijos atskirai</p></div><div class="tablewrap"><table><thead><tr><th>Darbuotojas</th><th>Faktiškai dirbta</th><th>Patvirtinta</th><th>Dirbtų ir atlikto darbo valandų skirtumas</th><th>Pravaikštų korekcijos</th><th>Korekcijų įrašai</th></tr></thead><tbody>${db.employees.filter(e=>rs.some(r=>r.employee===e.id)).map(e=>{const er=rs.filter(r=>r.employee===e.id);const delta=num(er,r=>R.assessed(r)-R.calculate(r).actual);return `<tr><td><button class="project-name" data-action="employee" data-id="${e.id}">${esc(e.name)}</button></td><td>${fmt(actual(er))} val.</td><td>${fmt(actual(er.filter(r=>r.status==='Patvirtinta')))} val.</td><td class="${delta<0?'negative':''}">${delta>0?'+':''}${fmt(delta)} val.</td><td>${fmt(num(er,r=>R.absenceAdjustment(db.entries,r)||0))} val.</td><td>${er.filter(r=>R.proposal(db.entries,r).delta!==0).length}</td></tr>`}).join('')}</tbody></table></div></section><div class="spacer"></div>${hint('Eksporte buhalterijai faktinės valandos ir vadovo siūlomos korekcijos yra atskiri stulpeliai. Įkainiai, darbo užmokesčio formulės ir automatinių išskaitų taikymas šiame prototipe neskaičiuojami.')}`;}
function expenseTable(rows){if(!director())return '';return `<section class="panel"><div class="panel-head"><h2>Būsto išlaidos</h2>${director()?B('Pridėti išlaidą','new-expense','','small'):''}</div><div class="tablewrap"><table><thead><tr><th>Objektas / būstas</th><th>Laikotarpis</th><th>Suma</th><th>Pastaba</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(project(e.project).name)}</strong><div class="meta">${esc(e.property)}</div></td><td>${e.from} – ${e.to}</td><td><strong>${money(e.amount)}</strong></td><td>${esc(e.note)}</td><td>${B('Keisti','edit-expense',`data-id="${e.id}"`,'small')}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Būsto išlaidų dar nėra.</td></tr>'}</tbody></table></div><div class="table-total"><span>Visos parodytos išlaidos</span><strong>${money(rows.reduce((s,e)=>s+e.amount,0))}</strong></div></section>`;}
function expensesView(){if(!director())return '';return head('Būsto išlaidos','Išlaidas įveda, keičia ir mato tik įmonės vadovas.',B(icon('plus')+' Pridėti išlaidą','new-expense','','primary'))+expenseTable(db.expenses);}
function requestsView(){const req=db.requests.filter(r=>admin()||r.author===state.user);return head(admin()?'Taisymo prašymai ir istorija':'Mano taisymo prašymai','Po įrašo išsaugojimo jį taiso tik administratorius, nurodydamas priežastį.')+`<section class="panel"><div class="panel-head"><h2>Taisymo prašymai</h2></div><div class="tablewrap"><table><thead><tr><th>Darbuotojas / data</th><th>Prašė</th><th>Paaiškinimas</th><th>Būsena</th><th></th></tr></thead><tbody>${req.map(q=>{const r=db.entries.find(r=>r.id===q.entry);return `<tr><td>${esc(employee(r.employee).name)}<div class="meta">${r.date}</div></td><td>${esc(user(q.author).name)}</td><td>${esc(q.comment)}</td><td>${badge(q.status)}</td><td>${corrector()&&q.status==='Laukia taisymo'?B('Taisyti įrašą','edit-time',`data-id="${r.id}"`,'small'):''}</td></tr>`}).join('')||'<tr><td colspan="5" class="empty">Taisymo prašymų nėra.</td></tr>'}</tbody></table></div></section>${admin()?`<div class="spacer"></div><section class="panel"><div class="panel-head"><h2>Pakeitimų istorija</h2><p>Kas, kada ir ką pakeitė</p></div><div class="tablewrap"><table><thead><tr><th>Kada / kas</th><th>Veiksmas</th><th>Priežastis ir informacija</th><th>Prieš</th><th>Po</th></tr></thead><tbody>${db.audit.filter(a=>director()||(a.scope!=='expenses'&&!/^Būsto išlaid/.test(a.action))).slice(0,100).map(a=>`<tr><td>${esc(a.when)}<div class="meta">${esc(a.actor)}</div></td><td>${esc(a.action)}</td><td>${esc(a.details)}</td><td class="audit-text">${esc(a.before)}</td><td class="audit-text">${esc(a.after)}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">Nauji veiksmai bus registruojami čia.</td></tr>'}</tbody></table></div></section>`:''}`;}
let returnFocus=null;
function openModal(title,body,label,submit){returnFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-head"><h2>${title}</h2><button type="button" class="icon-btn" data-action="close" aria-label="Uždaryti">${icon('close')}</button></header><form id="modal-form"><div class="modal-body">${body}<p id="form-error" class="error" role="alert"></p></div><footer class="modal-footer">${B('Atšaukti','close')}<button type="submit" class="btn primary">${label}</button></footer></form></section></div>`;document.body.style.overflow='hidden';$('#modal-form').onsubmit=e=>{e.preventDefault();try{submit(Object.fromEntries(new FormData(e.target)),e.target)}catch(error){$('#form-error').textContent=error.message}};$('#modal-form').querySelector('input, select, textarea, button').focus();}
function closeModal(){$('#modal-root').innerHTML='';document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus();}
const snapshot=r=>`${employee(r.employee).name}; ${r.date}; ${project(r.project).name}; ${r.attendance}; ${r.start||'—'}–${r.end||'—'}; pietūs ${r.lunchStart}; faktas ${fmt(R.calculate(r).actual)}; vadovo siūlymas ${R.proposal(db.entries,r).value??'neapskaičiuotas'}; ${r.comment}`;
function timeModal(id){const current=id?db.entries.find(r=>r.id===+id):null;if(current&&!corrector())return;const chosenTeam=current?.team||actor().team||1;const currentActor=current?user(current.author):actor();
 const body=`${current?field('Darbuotojas',`<input value="${esc(employee(current.employee).name)}" disabled>`):`${field('Komanda',select('team',options(db.teams,chosenTeam,t=>t.name)))}<div class="field"><label>Darbuotojai *</label><input id="people-search" placeholder="Ieškoti darbuotojo visame sąraše" aria-label="Ieškoti darbuotojo įvedimui"><div class="picker-toolbar">${B('Pažymėti komandos darbuotojus','select-team','','small')}${B('Nuimti žymėjimus','clear-people','','small')}</div><div class="checkboxes people-picker" id="people-picker"></div><small id="people-note">Pasirinkite darbuotojus. Sutampantys intervalai neleidžiami.</small></div>`}<div class="form-grid">${field('Objektas *',select('project',projectOptions(current?.project||state.project)))}${field('Data *',`<input name="date" type="date" required value="${current?.date||TODAY}">`)}</div>${current?field('Komanda',select('team',options(db.teams,chosenTeam,t=>t.name))):''}${admin()?field('Duomenis pildantis vadovas',select('author',options(db.users.filter(u=>u.kind==='supervisor'),current?.author||db.users.find(u=>u.team===chosenTeam).id,u=>u.name+' · '+team(u.team).name))):`<p class="meta">Pildo: ${esc(currentActor.name)}</p><div class="spacer"></div>`}${field('Dalyvavimas',select('attendance',['Dirbo','Nepateisintas neatvykimas','Pateisintas neatvykimas'].map(v=>`<option ${current?.attendance===v?'selected':''}>${v}</option>`).join('')))}<div id="time-fields"><div class="form-grid">${field('Darbo pradžia *',`<input type="time" name="start" value="${current?.start||'07:00'}" required>`)}${field('Darbo pabaiga *',`<input type="time" name="end" value="${current?.end||'17:00'}" required>`)}</div>${field('30 min. pietų pradžia',`<input type="time" name="lunchStart" value="${current?.lunchStart||'12:00'}" required>`,'Visuose to darbuotojo dienos įrašuose pietų pradžia turi sutapti.')}<div class="calculated"><span>Automatiškai apskaičiuota vienam žmogui</span><strong id="calculated-hours">—</strong></div>${field('Atlikto darbo valandos',`<input name="proposedHours" type="number" step="0.01" min="0" value="${current?.proposedHours??''}" placeholder="Tuščia = faktinės valandos">`,'Faktinis laikas nekeičiamas. Skirtumui privalomas komentaras.')}</div><div id="absence-note" hidden>${hint('Neatvykus faktas yra 0 val. Nepateisinto neatvykimo atveju atskirai rodomas neigiamas kitų komandos darbuotojų tos dienos vidurkis. Tai siūlymas peržiūrai, o ne automatinė darbo užmokesčio išskaita.')}<div class="spacer"></div></div><div class="form-grid">${field('Automobilis',`<select name="vehicle"><option value="">Nepriskirta</option>${options(db.vehicles,current?.vehicle||team(chosenTeam).vehicle,v=>v.plate+' · '+v.name)}</select>`)}${field('Vairuotojas (jei žinoma)',`<select name="driver"><option value="">Nenurodyta</option>${options(db.employees,current?.driver||'',e=>e.name)}</select>`)}</div>${field('Vadovo komentaras',`<textarea name="comment" placeholder="Neatvykimo arba valandų skirtumo paaiškinimas…">${esc(current?.comment||'')}</textarea>`)}${current?field('Taisymo priežastis *','<textarea name="correctionReason" required placeholder="Kas buvo neteisinga ir kodėl keičiama?"></textarea>'):''}`;
 openModal(current?'Administratoriaus pataisymas':'Suvesti komandos dieną',body,current?'Išsaugoti pataisymą':'Įrašyti dieną',(f,form)=>{
  const ids=current?[current.employee]:[...checked];if(!ids.length)throw Error('Pasirinkite bent vieną darbuotoją.');
  const absence=f.attendance!=='Dirbo';const owner=admin()?+f.author:state.user;const data={project:+f.project,date:f.date,team:+f.team,author:owner,attendance:f.attendance,start:absence?'':f.start,end:absence?'':f.end,lunchStart:f.lunchStart||'12:00',vehicle:+f.vehicle||null,driver:+f.driver||null,proposedHours:absence?null:f.proposedHours===''?null:+f.proposedHours,comment:f.comment.trim(),status:'Pateikta',approvedProposal:null};
  const c=R.calculate(data);if(!absence&&data.proposedHours!==null&&data.proposedHours!==c.actual&&!data.comment)throw Error('Valandų skirtumui įrašykite komentarą.');if(absence&&!data.comment)throw Error('Neatvykimui reikia paaiškinimo.');if(current&&!f.correctionReason.trim())throw Error('Nurodykite taisymo priežastį.');
  for(const eid of ids){const candidate={...data,employee:eid};if(R.conflicts(db.entries,candidate,current?.id).length)throw Error(`${employee(eid).name}: šiai dienai jau yra neatvykimas arba sutampantis darbo laikas.`);const day=db.entries.filter(r=>r.id!==current?.id&&r.employee===eid&&r.date===f.date&&r.attendance==='Dirbo');if(!absence&&day.some(r=>r.lunchStart!==data.lunchStart))throw Error(`${employee(eid).name}: visų dienos įrašų pietų pradžia turi sutapti.`);}
  if(!absence&&data.vehicle&&db.entries.some(r=>r.id!==current?.id&&r.vehicle===data.vehicle&&r.team!==data.team&&r.date===data.date&&r.attendance==='Dirbo'&&data.start<r.end&&data.end>r.start))throw Error('Šiuo intervalu automobilis jau priskirtas kitai komandai.');
  if(current){const before=snapshot(current);Object.assign(current,data);audit('Pakeistas valandų įrašas',f.correctionReason.trim(),before,snapshot(current));for(const q of db.requests.filter(q=>q.entry===current.id&&q.status==='Laukia taisymo'))q.status='Išspręsta';}else{for(const eid of ids){const row={id:nextId(db.entries),employee:eid,...data};db.entries.push(row);audit('Įvestos valandos',employee(eid).name,'',snapshot(row));}}
  if(!project(data.project).managers.includes(owner))project(data.project).managers.push(owner);
  save();closeModal();render();toast(current?'Pataisymas išsaugotas istorijoje. Įrašą reikia patvirtinti.':`Įrašyta ${ids.length} darbuotojų. Valandos pateiktos administratoriui.`);
 });
 const form=$('#modal-form');const checked=new Set();
 function redrawPeople(){if(current)return;const f=Object.fromEntries(new FormData(form));const q=($('#people-search').value||'').toLowerCase();const crew=+f.team;const all=q?db.employees.filter(e=>e.name.toLowerCase().includes(q)):db.employees.filter(e=>e.team===crew);$('#people-picker').innerHTML=all.map(e=>{const occupied=R.conflicts(db.entries,{employee:e.id,date:f.date,start:f.start,end:f.end,attendance:f.attendance}).length>0;return `<label class="${occupied?'occupied':''}"><input type="checkbox" name="people" value="${e.id}" ${checked.has(e.id)?'checked':''} ${occupied?'disabled':''}>${esc(e.name)}${occupied?'<small>Užimtas</small>':''}</label>`}).join('');$('#people-note').textContent=`Pasirinkta ${checked.size}. Užimti darbuotojai nepasiekiami pasirinktam intervalui. Norėdami perkelti žmogų, rinkitės kitą intervalą.`;}
 function recalc(){const f=Object.fromEntries(new FormData(form));const absence=f.attendance!=='Dirbo';$('#time-fields').hidden=absence;$('#absence-note').hidden=!absence;form.querySelector('[name=start]').required=!absence;form.querySelector('[name=end]').required=!absence;try{$('#calculated-hours').textContent=fmt(R.calculate(f).actual)+' val.'}catch{$('#calculated-hours').textContent='Patikrinkite laiką'};redrawPeople();}
 if(!current){$('#people-picker').onchange=e=>{if(e.target.name==='people'){if(e.target.checked)checked.add(+e.target.value);else checked.delete(+e.target.value);}};$('#people-search').oninput=redrawPeople;form.querySelector('[data-action=select-team]').onclick=()=>{const f=Object.fromEntries(new FormData(form));for(const e of db.employees.filter(e=>e.team===+f.team))if(!R.conflicts(db.entries,{employee:e.id,date:f.date,start:f.start,end:f.end,attendance:f.attendance}).length)checked.add(e.id);redrawPeople()};form.querySelector('[data-action=clear-people]').onclick=()=>{checked.clear();redrawPeople()};}
 form.addEventListener('change',e=>{if(e.target.name==='team'&&!current){checked.clear();const t=team(+e.target.value);form.querySelector('[name=vehicle]').value=t.vehicle;if(admin())form.querySelector('[name=author]').value=db.users.find(u=>u.team===t.id)?.id;}if(['team','date','start','end','lunchStart','attendance'].includes(e.target.name))recalc();});recalc();
}
function requestFix(id){const r=db.entries.find(r=>r.id===+id);if(admin()||r.author!==state.user)return;openModal('Prašymas administratoriui',`<p class="subtitle">${esc(employee(r.employee).name)} · ${r.date}</p><div class="spacer"></div>${field('Ką reikia pataisyti? *','<textarea name="comment" required placeholder="Nurodykite teisingą laiką, objektą ar kitą pataisymą…"></textarea>')}`,'Pateikti prašymą',f=>{if(!f.comment.trim())throw Error('Aprašykite pataisymą.');db.requests.push({id:nextId(db.requests),entry:r.id,author:state.user,comment:f.comment.trim(),status:'Laukia taisymo'});audit('Prašymas pataisyti',f.comment.trim());save();closeModal();render();toast('Prašymas pateiktas. Pats valandų įrašas nepakeistas.');});}
function projectModal(id){if(!admin())return;const p=id?project(id):null;openModal(p?'Keisti objektą':'Pridėti objektą',`${field('Objekto pavadinimas *',`<input name="name" required value="${esc(p?.name||'')}">`)}${field('Vieta',`<input name="city" value="${esc(p?.city||'')}">`)}<div class="form-grid">${field('Galia, MW (nebūtina)',`<input type="number" min="0" step="0.01" name="mw" value="${p?.mw||''}">`)}${field('Būsena',select('status',['Planuojamas','Vykdomas','Užbaigtas'].map(v=>`<option ${p?.status===v?'selected':''}>${v}</option>`).join('')))}</div><div class="field"><label>Objektą pildantys vadovai</label><div class="checkboxes">${db.users.filter(u=>u.kind==='supervisor').map(u=>`<label><input type="checkbox" name="managers" value="${u.id}" ${p?.managers.includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</div><small>Galima priskirti kelis vadovus tam pačiam objektui.</small></div>`,'Išsaugoti',(f,form)=>{if(!f.name.trim())throw Error('Įveskite objekto pavadinimą.');if(db.projects.some(x=>x.id!==p?.id&&x.name.trim().toLowerCase()===f.name.trim().toLowerCase()))throw Error('Toks objekto pavadinimas jau naudojamas.');const v={name:f.name.trim(),city:f.city.trim(),mw:f.mw?+f.mw:null,status:f.status,managers:[...form.querySelectorAll('[name=managers]:checked')].map(e=>+e.value)};if(p)Object.assign(p,v);else db.projects.push({id:nextId(db.projects),...v});audit('Objekto duomenys',v.name);save();closeModal();render();toast('Objektas išsaugotas.');});}
function employeeModal(){if(!admin())return;openModal('Pridėti darbuotoją',`${field('Vardas ir pavardė *','<input name="name" required>')}${field('Komanda',select('team',options(db.teams,1,t=>t.name)))}${field('Pareigos *','<input name="job" required value="Montuotojas">')}`,'Pridėti',f=>{if(!f.name.trim()||!f.job.trim())throw Error('Užpildykite vardą ir pareigas.');db.employees.push({id:nextId(db.employees),name:f.name.trim(),team:+f.team,job:f.job.trim(),active:true});audit('Pridėtas darbuotojas',f.name.trim());save();closeModal();render();toast('Darbuotojas pridėtas.');});}
function vehicleModal(id){if(!admin())return;const v=id?vehicle(id):null;openModal(v?'Automobilio duomenys':'Pridėti automobilį',`<div class="form-grid">${field('Valstybinis numeris *',`<input name="plate" required value="${esc(v?.plate||'')}">`)}${field('Markė / modelis *',`<input name="name" required value="${esc(v?.name||'')}">`)}${field('Techninė apžiūra iki *',`<input type="date" name="technicalDue" required value="${v?.technicalDue||''}">`)}${field('Priminti prieš, dienų *',`<input name="remindDays" type="number" min="1" max="180" required value="${v?.remindDays||30}">`)}</div>${field('Atsakingo asmens el. paštas',`<input name="responsible" type="email" value="${esc(v?.responsible||'')}" placeholder="vardas@imone.lt">`,'Siuntimo integracija bus prijungiama kuriant sistemą.')}`,'Išsaugoti',f=>{if(!f.plate.trim()||!f.name.trim())throw Error('Užpildykite automobilio duomenis.');if(db.vehicles.some(x=>x.id!==v?.id&&x.plate.trim().toLowerCase()===f.plate.trim().toLowerCase()))throw Error('Toks automobilio numeris jau yra.');const value={plate:f.plate.trim(),name:f.name.trim(),technicalDue:f.technicalDue,remindDays:+f.remindDays,responsible:f.responsible};if(v)Object.assign(v,value);else db.vehicles.push({id:nextId(db.vehicles),...value});audit('Automobilio duomenys',value.plate);save();closeModal();render();toast('Automobilis išsaugotas.');});}
function expenseModal(id){if(!director())return;const e=id?db.expenses.find(e=>e.id===+id):null;openModal(e?'Keisti būsto išlaidą':'Būsto išlaida',`${field('Objektas',select('project',projectOptions(e?.project||state.project)))}${field('Būsto pavadinimas / adresas *',`<input name="property" required value="${esc(e?.property||'')}">`)}<div class="form-grid">${field('Nuo *',`<input name="from" type="date" required value="${e?.from||TODAY}">`)}${field('Iki *',`<input name="to" type="date" required value="${e?.to||TODAY}">`)}</div>${field('Suma, € *',`<input name="amount" type="number" step="0.01" min="0" required value="${e?.amount??''}">`)}${field('Pastaba',`<textarea name="note">${esc(e?.note||'')}</textarea>`)}`,'Išsaugoti',f=>{if(!director())throw Error('Išlaidas gali keisti tik įmonės vadovas.');if(f.to<f.from)throw Error('Patikrinkite išlaidos laikotarpį.');if(!f.property.trim())throw Error('Įveskite būsto pavadinimą.');const value={project:+f.project,property:f.property.trim(),from:f.from,to:f.to,amount:+f.amount,note:f.note.trim(),author:state.user};if(e)Object.assign(e,value);else db.expenses.push({id:nextId(db.expenses),...value});audit('Būsto išlaida',`${project(value.project).name}: ${money(value.amount)}`,'','','expenses');save();closeModal();render();toast('Išlaida priskirta objektui.');});}
function exportCSV(mode){let rows=periodRows();if(mode==='project')rows=rows.filter(r=>r.project===state.project);if(mode==='employee')rows=rows.filter(r=>r.employee===state.employee);if(mode==='approved')rows=rows.filter(r=>r.status==='Patvirtinta');const cell=v=>{const raw=typeof v==='number'?String(v).replace('.',','):String(v??'').replace(/^[=+@\-]/,"'$&");return '"'+raw.replace(/"/g,'""')+'"'};const data=[['Darbuotojas','Data','Objektas','Komanda','Duomenis pildęs vadovas','Automobilis','Vairuotojas','Dalyvavimas','Pradžia','Pabaiga','Pietūs min.','Faktinės valandos','Atlikto darbo įvertinimas, val.','Atlikto darbo skirtumas','Pravaikštos korekcija','Komentaras','Būsena'],...rows.map(r=>{const c=R.calculate(r),p=R.proposal(db.entries,r);return [employee(r.employee).name,r.date,project(r.project).name,team(r.team).name,user(r.author)?.name,vehicle(r.vehicle)?.plate,employee(r.driver)?.name,r.attendance,r.start,r.end,c.lunch,c.actual,R.assessed(r),R.round(R.assessed(r)-c.actual),R.absenceAdjustment(db.entries,r)??'Neapskaičiuota',r.comment,r.status]})];const name=mode==='employee'?employee(state.employee).name:mode==='project'?project(state.project).name:'Valandu_suvestine';const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name.replace(/[^\p{L}\p{N}_-]/gu,'_')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Paruošti ${rows.length} įrašai eksportui.`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=+b.dataset.id;
 if(action==='nav'){state.page=b.dataset.page;resetFilters();render();window.scrollTo(0,0)}
 if(action==='detail'){state.project=id;state.page='detail';resetFilters();render();window.scrollTo(0,0)}
 if(action==='employee'){state.employee=id;state.page='employee';resetFilters();render();window.scrollTo(0,0)}
 if(action==='page'){state.pageNumber=+b.dataset.pageNumber;render()}
 if(action==='new-time')openDaySheet();if(action==='day-sheet')openDaySheet(id);if(action==='edit-time')timeModal(id);if(action==='close')closeModal();if(action==='request-fix')requestFix(id);
 if(action==='new-project')projectModal();if(action==='edit-project')projectModal(id);if(action==='new-employee')employeeModal();if(action==='new-vehicle')vehicleModal();if(action==='edit-vehicle')vehicleModal(id);if(action==='new-expense')expenseModal();if(action==='edit-expense')expenseModal(id);
 if(action==='approve'&&admin()){const r=db.entries.find(r=>r.id===id);if(r.status==='Pateikta'){const proposed=R.proposal(db.entries,r);r.approvedProposal={value:proposed.value,delta:proposed.delta,reference:proposed.reference};r.status='Patvirtinta';audit('Patvirtintas įrašas',employee(r.employee).name+' · '+r.date,'',snapshot(r));save();render();toast('Faktinis įrašas ir vadovo pastaba peržiūrėti. Darbo užmokestis neperskaičiuojamas.');}}
 if(action==='export-time')exportCSV('all');if(action==='export-approved')exportCSV('approved');if(action==='export-project')exportCSV('project');if(action==='export-employee')exportCSV('employee');
 if(action==='reset')openModal('Atkurti demonstracinius duomenis','<p>Bus atkurti 70 išgalvotų darbuotojų ir 27 automobilių pavyzdžiai. Šio demo įrašyti pakeitimai bus pašalinti.</p>','Atkurti',()=>{db=seed();save();closeModal();state.page='overview';render();toast('Demo duomenys atkurti.');});
});
document.addEventListener('keydown',e=>{const modal=$('#modal-root .modal');if(!modal)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const elements=[...modal.querySelectorAll('button,input,select,textarea')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
